    private const string FullAttributeName = $"{AttributeNamespace}.{AttributeName}";

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        // Register the attribute itself
        context.RegisterPostInitializationOutput(ctx =>
        {
            ctx.AddSource("KyrolusAotEndpointAttribute.g.cs", SourceText.From(AttributeSource, Encoding.UTF8));
            ctx.AddSource("KyrolusPropertyAccessor.g.cs", SourceText.From(PropertyAccessorBaseSource, Encoding.UTF8));
            ctx.AddSource("KyrolusStaticFilterBuilder.g.cs", SourceText.From(StaticFilterBuilderBaseSource, Encoding.UTF8));
            ctx.AddSource("KyrolusStaticOrderBuilder.g.cs", SourceText.From(StaticOrderBuilderBaseSource, Encoding.UTF8));
        });

        // Find all types marked with [KyrolusAotEndpoint]
        var classesWithAttribute = context.SyntaxProvider.ForAttributeWithMetadataName(
            FullAttributeName,
            predicate: static (node, _) => node is ClassDeclarationSyntax or RecordDeclarationSyntax,
            transform: static (ctx, ct) => ExtractEndpointInfo(ctx, ct)
        ).Where(static info => info is not null);

        var compilationAndClasses = context.CompilationProvider.Combine(classesWithAttribute.Collect());

        context.RegisterSourceOutput(compilationAndClasses, Execute);
    }

    private static EndpointInfo? ExtractEndpointInfo(GeneratorAttributeSyntaxContext ctx, CancellationToken ct)
    {
        var symbol = ctx.TargetSymbol as INamedTypeSymbol;
        if (symbol is null || symbol.IsAbstract)
            return null;

        var attributeData = ctx.Attributes.FirstOrDefault();
        if (attributeData is null)
            return null;

        // Extract attribute properties
        string? keyProperty = null;
        ITypeSymbol? keyType = null;
        string? softDeleteProperty = null;
        string? rowVersionProperty = null;
        string? tenantIdProperty = null;
        bool enableFiltering = true;
        bool enableOrdering = true;
        string[]? allowedFilterProperties = null;
        string[]? allowedOrderProperties = null;

        foreach (var named in attributeData.NamedArguments)
        {
            switch (named.Key)
            {
                case "KeyProperty":
                    keyProperty = named.Value.Value as string;
                    break;
                case "KeyType":
                    keyType = named.Value.Value as ITypeSymbol;
                    break;
                case "SoftDeleteProperty":
                    softDeleteProperty = named.Value.Value as string;
                    break;
                case "RowVersionProperty":
                    rowVersionProperty = named.Value.Value as string;
                    break;
                case "TenantIdProperty":
                    tenantIdProperty = named.Value.Value as string;
                    break;
                case "EnableFiltering":
                    enableFiltering = named.Value.Value is bool b && b;
                    break;
                case "EnableOrdering":
                    enableOrdering = named.Value.Value is bool b2 && b2;
                    break;
                case "AllowedFilterProperties":
                    allowedFilterProperties = ExtractStringArray(named.Value);
                    break;
                case "AllowedOrderProperties":
                    allowedOrderProperties = ExtractStringArray(named.Value);
                    break;
            }
        }

        // Also get from constructor args
        if (attributeData.ConstructorArguments.Length > 0)
        {
            var firstArg = attributeData.ConstructorArguments[0];
            if (firstArg.Value is string kp)
            {
                keyProperty = kp;
            }
        }

        // Default key property to "Id"
        keyProperty ??= "Id";

        // Try to find key type from property
        if (keyType is null)
        {
            var prop = symbol.GetMembers()
                .OfType<IPropertySymbol>()
                .FirstOrDefault(p => string.Equals(p.Name, keyProperty, StringComparison.OrdinalIgnoreCase));
            keyType = prop?.Type;
        }

        // Collect all public properties
        var properties = symbol.GetMembers()
            .OfType<IPropertySymbol>()
            .Where(p => p.DeclaredAccessibility == Accessibility.Public && !p.IsStatic && p.GetMethod is not null)
            .Select(p => new PropertyInfo(
                p.Name,
                p.Type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat),
                p.Type.ToDisplayString(SymbolDisplayFormat.MinimallyQualifiedFormat),
                p.SetMethod is not null,
                IsNullableType(p.Type),
                GetUnderlyingType(p.Type),
                IsNumericType(p.Type),
                IsStringType(p.Type),
                IsBooleanType(p.Type),
                IsDateTimeType(p.Type),
                IsGuidType(p.Type),
                IsEnumType(p.Type),
                IsCollectionType(p.Type),
                GetCollectionElementType(p.Type)))
            .ToImmutableArray();

        return new EndpointInfo(
            symbol.Name,
            symbol.ContainingNamespace.ToDisplayString(),
            symbol.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat),
            keyProperty,
            keyType?.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat) ?? "int",
            softDeleteProperty,
            rowVersionProperty,
            tenantIdProperty,
            enableFiltering,
            enableOrdering,
            allowedFilterProperties?.ToImmutableArray() ?? ImmutableArray<string>.Empty,
            allowedOrderProperties?.ToImmutableArray() ?? ImmutableArray<string>.Empty,
            properties);
    }

    private static string[]? ExtractStringArray(TypedConstant constant)
    {
        if (constant.Kind == TypedConstantKind.Array && !constant.Values.IsDefaultOrEmpty)
        {
            return constant.Values
                .Where(v => v.Value is string)
                .Select(v => (string)v.Value!)
                .ToArray();
        }
        return null;
    }

    private static bool IsNullableType(ITypeSymbol type)
    {
        if (type.NullableAnnotation == NullableAnnotation.Annotated)
            return true;
        if (type is INamedTypeSymbol named && named.IsGenericType)
        {
            return named.ConstructedFrom.ToDisplayString() == "System.Nullable<T>";
        }
        return false;
    }

    private static string? GetUnderlyingType(ITypeSymbol type)
    {
        if (type is INamedTypeSymbol named && named.IsGenericType &&
            named.ConstructedFrom.ToDisplayString() == "System.Nullable<T>")
        {
            return named.TypeArguments[0].ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
        }
        return null;
    }

    private static bool IsNumericType(ITypeSymbol type)
    {
        var underlying = GetUnderlyingTypeSymbol(type) ?? type;
        return underlying.SpecialType switch
        {
            SpecialType.System_Int16 or SpecialType.System_Int32 or SpecialType.System_Int64 or
            SpecialType.System_UInt16 or SpecialType.System_UInt32 or SpecialType.System_UInt64 or
            SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal or
            SpecialType.System_Byte or SpecialType.System_SByte => true,
            _ => false
        };
    }

    private static bool IsStringType(ITypeSymbol type) =>
        (GetUnderlyingTypeSymbol(type) ?? type).SpecialType == SpecialType.System_String;

    private static bool IsBooleanType(ITypeSymbol type) =>
        (GetUnderlyingTypeSymbol(type) ?? type).SpecialType == SpecialType.System_Boolean;

    private static bool IsDateTimeType(ITypeSymbol type)
    {
        var underlying = GetUnderlyingTypeSymbol(type) ?? type;
        var name = underlying.ToDisplayString();
        return name is "System.DateTime" or "System.DateTimeOffset" or "System.DateOnly" or "System.TimeOnly";
    }

    private static bool IsGuidType(ITypeSymbol type)
    {
        var underlying = GetUnderlyingTypeSymbol(type) ?? type;
        return underlying.ToDisplayString() == "System.Guid";
    }

    private static bool IsEnumType(ITypeSymbol type)
    {
        var underlying = GetUnderlyingTypeSymbol(type) ?? type;
        return underlying.TypeKind == TypeKind.Enum;
    }

    private static bool IsCollectionType(ITypeSymbol type)
    {
        if (type is not INamedTypeSymbol named) return false;
        var interfaces = named.AllInterfaces;
        return interfaces.Any(i => i.ToDisplayString().StartsWith("System.Collections.Generic.IEnumerable<", StringComparison.Ordinal));
    }

    private static string? GetCollectionElementType(ITypeSymbol type)
    {
        if (type is not INamedTypeSymbol named) return null;
        var enumerable = named.AllInterfaces.FirstOrDefault(i =>
            i.OriginalDefinition.ToDisplayString() == "System.Collections.Generic.IEnumerable<T>");
        return enumerable?.TypeArguments.FirstOrDefault()?.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
    }

    private static ITypeSymbol? GetUnderlyingTypeSymbol(ITypeSymbol type)
    {
        if (type is INamedTypeSymbol named && named.IsGenericType &&
            named.ConstructedFrom.ToDisplayString() == "System.Nullable<T>")
        {
            return named.TypeArguments[0];
        }
        return null;
    }

    private void Execute(SourceProductionContext context, (Compilation compilation, ImmutableArray<EndpointInfo?> endpoints) tuple)
    {
        var (_, endpoints) = tuple;
        var validEndpoints = endpoints.Where(e => e is not null).Select(e => e!).ToList();
        if (validEndpoints.Count == 0) return;

        var namespaces = new HashSet<string>(StringComparer.Ordinal);
        var registrations = new List<string>();

        foreach (var endpoint in validEndpoints)
        {
            // Generate property accessor
            var accessorSource = GeneratePropertyAccessor(endpoint);
            context.AddSource($"{endpoint.TypeName}PropertyAccessor.g.cs", SourceText.From(accessorSource, Encoding.UTF8));

            // Generate filter builder
            if (endpoint.EnableFiltering)
            {
                var filterSource = GenerateFilterBuilder(endpoint);
                context.AddSource($"{endpoint.TypeName}FilterBuilder.g.cs", SourceText.From(filterSource, Encoding.UTF8));
            }

            // Generate order builder
            if (endpoint.EnableOrdering)
            {
                var orderSource = GenerateOrderBuilder(endpoint);
                context.AddSource($"{endpoint.TypeName}OrderBuilder.g.cs", SourceText.From(orderSource, Encoding.UTF8));
            }

            namespaces.Add(endpoint.Namespace);
            registrations.Add($"            services.AddSingleton<IKyrolusPropertyAccessor<{endpoint.FullTypeName}>, {endpoint.TypeName}PropertyAccessor>();");
            if (endpoint.EnableFiltering)
            {
                registrations.Add($"            services.AddSingleton<IKyrolusStaticFilterBuilder<{endpoint.FullTypeName}>, {endpoint.TypeName}FilterBuilder>();");
            }
            if (endpoint.EnableOrdering)
            {
                registrations.Add($"            services.AddSingleton<IKyrolusStaticOrderBuilder<{endpoint.FullTypeName}>, {endpoint.TypeName}OrderBuilder>();");
            }
        }

        // Generate DI extensions
        EmitDiExtensions(context, namespaces, registrations);

        // Generate endpoint handler registration helper
        EmitEndpointHandlerRegistry(context, validEndpoints);
    }

    private string GeneratePropertyAccessor(EndpointInfo endpoint)
