        sb.AppendLine($"    public sealed class {endpoint.TypeName}PropertyAccessor : IKyrolusPropertyAccessor<{endpoint.FullTypeName}>");
        sb.AppendLine("    {");

        // Static property info cache
        sb.AppendLine("        private static readonly Dictionary<string, KyrolusPropertyInfo> _propertyMap = new(StringComparer.OrdinalIgnoreCase)");
        sb.AppendLine("        {");
        foreach (var prop in endpoint.Properties)
