    private void GeneratePropertyFilterMethod(StringBuilder sb, EndpointInfo endpoint, PropertyInfo prop)
    {
        sb.AppendLine($"        private static bool TryBuild{prop.Name}Filter(");
        sb.AppendLine("            string op,");
        sb.AppendLine("            string? value,");
        sb.AppendLine($"            out Expression<Func<{endpoint.FullTypeName}, bool>>? expression,");
        sb.AppendLine("            out string? error)");
        sb.AppendLine("        {");
        sb.AppendLine("            expression = null;");
        sb.AppendLine("            error = null;");
        sb.AppendLine();

        // Handle null checks first
        sb.AppendLine("            if (op == \"isnull\")");
        sb.AppendLine("            {");
        if (prop.IsNullable || prop.IsString)
        {
            sb.AppendLine($"                expression = x => x.{prop.Name} == null;");
        }
        else
        {
            sb.AppendLine($"                expression = x => false; // {prop.Name} is non-nullable");
        }
        sb.AppendLine("                return true;");
        sb.AppendLine("            }");
        sb.AppendLine();

        sb.AppendLine("            if (op == \"notnull\")");
        sb.AppendLine("            {");
        if (prop.IsNullable || prop.IsString)
        {
            sb.AppendLine($"                expression = x => x.{prop.Name} != null;");
        }
        else
        {
            sb.AppendLine($"                expression = x => true; // {prop.Name} is non-nullable");
        }
        sb.AppendLine("                return true;");
        sb.AppendLine("            }");
        sb.AppendLine();

        // Type-specific operations
        if (prop.IsString)
        {
            GenerateStringFilterOperations(sb, prop);
        }
        else if (prop.IsNumeric)
        {
            GenerateNumericFilterOperations(sb, prop);
        }
        else if (prop.IsBoolean)
        {
            GenerateBooleanFilterOperations(sb, prop);
        }
        else if (prop.IsDateTime)
        {
            GenerateDateTimeFilterOperations(sb, prop);
        }
        else if (prop.IsGuid)
        {
            GenerateGuidFilterOperations(sb, prop);
        }
        else if (prop.IsEnum)
        {
            GenerateEnumFilterOperations(sb, prop);
        }
        else
        {
            // Default: only eq supported
            sb.AppendLine("            if (op == \"eq\")");
            sb.AppendLine("            {");
            sb.AppendLine($"                error = \"Only 'eq' operator is supported for {prop.Name}.\";");
            sb.AppendLine("                return false;");
            sb.AppendLine("            }");
        }

        sb.AppendLine();
        sb.AppendLine($"            error = $\"Operator '{{op}}' is not supported for property '{prop.Name}'.\";");
        sb.AppendLine("            return false;");
        sb.AppendLine("        }");
        sb.AppendLine();
    }

    private void GenerateStringFilterOperations(StringBuilder sb, PropertyInfo prop)
    {
        sb.AppendLine("            if (string.IsNullOrEmpty(value))");
        sb.AppendLine("            {");
        sb.AppendLine("                error = \"Value is required for string comparison.\";");
        sb.AppendLine("                return false;");
        sb.AppendLine("            }");
        sb.AppendLine();
        sb.AppendLine("            switch (op)");
        sb.AppendLine("            {");
        sb.AppendLine("                case \"eq\":");
        sb.AppendLine($"                    expression = x => x.{prop.Name} == value;");
        sb.AppendLine("                    return true;");
        sb.AppendLine("                case \"ne\":");
        sb.AppendLine($"                    expression = x => x.{prop.Name} != value;");
        sb.AppendLine("                    return true;");
        sb.AppendLine("                case \"contains\":");
        sb.AppendLine($"                    expression = x => x.{prop.Name} != null && x.{prop.Name}.Contains(value);");
        sb.AppendLine("                    return true;");
        sb.AppendLine("                case \"startswith\":");
        sb.AppendLine($"                    expression = x => x.{prop.Name} != null && x.{prop.Name}.StartsWith(value);");
        sb.AppendLine("                    return true;");
        sb.AppendLine("                case \"endswith\":");
        sb.AppendLine($"                    expression = x => x.{prop.Name} != null && x.{prop.Name}.EndsWith(value);");
        sb.AppendLine("                    return true;");
        sb.AppendLine("            }");
    }

