        sb.AppendLine("                    return true;");
        sb.AppendLine("                case \"lte\":");
        sb.AppendLine($"                    expression = x => x.{prop.Name} <= parsed;");
        sb.AppendLine("                    return true;");
        sb.AppendLine("            }");
    }

