        sb.AppendLine("            if (!Guid.TryParse(value, out var parsed))");
        sb.AppendLine("            {");
        sb.AppendLine($"                error = $\"Could not convert '{{value}}' to Guid.\";");
        sb.AppendLine("                return false;");
        sb.AppendLine("            }");
        sb.AppendLine();
        sb.AppendLine("            if (op == \"eq\")");
        sb.AppendLine("            {");
        sb.AppendLine($"                expression = x => x.{prop.Name} == parsed;");
        sb.AppendLine("                return true;");
        sb.AppendLine("            }");
        sb.AppendLine("            if (op == \"ne\")");
        sb.AppendLine("            {");
        sb.AppendLine($"                expression = x => x.{prop.Name} != parsed;");
        sb.AppendLine("                return true;");
        sb.AppendLine("            }");
    }

    private void GenerateEnumFilterOperations(StringBuilder sb, PropertyInfo prop)
    {
        var underlyingType = prop.UnderlyingType ?? prop.FullTypeName;
        sb.AppendLine($"            if (!Enum.TryParse<{underlyingType}>(value, true, out var parsed))");
        sb.AppendLine("            {");
        sb.AppendLine($"                error = $\"Could not convert '{{value}}' to {prop.ShortTypeName}.\";");
        sb.AppendLine("                return false;");
        sb.AppendLine("            }");
        sb.AppendLine();
        sb.AppendLine("            if (op == \"eq\")");
        sb.AppendLine("            {");
        sb.AppendLine($"                expression = x => x.{prop.Name} == parsed;");
        sb.AppendLine("                return true;");
        sb.AppendLine("            }");
        sb.AppendLine("            if (op == \"ne\")");
        sb.AppendLine("            {");
        sb.AppendLine($"                expression = x => x.{prop.Name} != parsed;");
        sb.AppendLine("                return true;");
        sb.AppendLine("            }");
