    private void GenerateFilterHelperMethods(StringBuilder sb)
    {
        sb.AppendLine(@"        private static string NormalizeOperator(string op)
        {
            var lower = op.Trim().ToLowerInvariant();
            return lower switch
            {
                ""="" or ""eq"" or ""equals"" => ""eq"",
                ""!="" or ""ne"" or ""notequals"" => ""ne"",
                "">"" or ""gt"" => ""gt"",
                "">="" or ""gte"" => ""gte"",
                ""<"" or ""lt"" => ""lt"",
                ""<="" or ""lte"" => ""lte"",
                _ => lower
            };
        }

        private static bool TryParseNumeric<T>(string? value, out T result) where T : struct
        {
            result = default;
            if (string.IsNullOrWhiteSpace(value)) return false;
            try
            {
                result = (T)Convert.ChangeType(value, typeof(T), CultureInfo.InvariantCulture);
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static bool TryParseDateTime(string? value, out DateTime result)
        {
            result = default;
            if (string.IsNullOrWhiteSpace(value)) return false;
            return DateTime.TryParse(value, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out result);
        }

        private static bool TryParseDateTime(string? value, out DateTimeOffset result)
        {
            result = default;
            if (string.IsNullOrWhiteSpace(value)) return false;
            return DateTimeOffset.TryParse(value, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out result);
        }");
    }

    private string GenerateOrderBuilder(EndpointInfo endpoint)
    {
        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated />");
        sb.AppendLine("#nullable enable");
        sb.AppendLine("using System;");
        sb.AppendLine("using System.Collections.Generic;");
        sb.AppendLine("using System.Linq;");
        sb.AppendLine("using System.Linq.Expressions;");
        sb.AppendLine("using KyrolusSous.EndpointKit.Core;");
        sb.AppendLine();
        sb.AppendLine($"namespace {endpoint.Namespace}");
        sb.AppendLine("{");
        sb.AppendLine($"    /// <summary>AOT-safe order expression builder for <see cref=\"{endpoint.TypeName}\"/>.</summary>");
        sb.AppendLine($"    public sealed class {endpoint.TypeName}OrderBuilder : IKyrolusStaticOrderBuilder<{endpoint.FullTypeName}>");
        sb.AppendLine("    {");

        // Allowed properties set
        if (!endpoint.AllowedOrderProperties.IsDefaultOrEmpty)
        {
            sb.AppendLine("        private static readonly HashSet<string> _allowedProperties = new(StringComparer.OrdinalIgnoreCase)");
            sb.AppendLine("        {");
            foreach (var prop in endpoint.AllowedOrderProperties)
            {
                sb.AppendLine($"            \"{prop}\",");
            }
            sb.AppendLine("        };");
            sb.AppendLine();
        }

        // TryBuildOrderExpression
        sb.AppendLine($"        public bool TryBuildOrderExpression(");
        sb.AppendLine("            string propertyName,");
        sb.AppendLine("            bool descending,");
        sb.AppendLine("            bool isFirst,");
        sb.AppendLine($"            IQueryable<{endpoint.FullTypeName}> query,");
        sb.AppendLine($"            out IOrderedQueryable<{endpoint.FullTypeName}>? result,");
        sb.AppendLine("            out string? error)");
        sb.AppendLine("        {");
        sb.AppendLine("            result = null;");
        sb.AppendLine("            error = null;");

        if (!endpoint.AllowedOrderProperties.IsDefaultOrEmpty)
        {
            sb.AppendLine("            if (!_allowedProperties.Contains(propertyName))");
            sb.AppendLine("            {");
            sb.AppendLine("                error = $\"Ordering by '{propertyName}' is not allowed.\";");
            sb.AppendLine("                return false;");
            sb.AppendLine("            }");
            sb.AppendLine();
        }

        sb.AppendLine("            switch (propertyName.ToLowerInvariant())");
        sb.AppendLine("            {");

        foreach (var prop in endpoint.Properties)
        {
            sb.AppendLine($"                case \"{prop.Name.ToLowerInvariant()}\":");
            sb.AppendLine("                    result = ApplyOrder(query, isFirst, descending,");
            sb.AppendLine($"                        x => x.{prop.Name});");
            sb.AppendLine("                    return true;");
        }

        sb.AppendLine("                default:");
        sb.AppendLine($"                    error = $\"Property '{{propertyName}}' not found on {endpoint.TypeName}.\";");
        sb.AppendLine("                    return false;");
        sb.AppendLine("            }");
        sb.AppendLine("        }");
        sb.AppendLine();

        // GetSupportedProperties
        sb.AppendLine("        public IReadOnlyList<string> GetSupportedProperties()");
        sb.AppendLine("            => new[]");
        sb.AppendLine("            {");
        foreach (var prop in endpoint.Properties)
        {
            sb.AppendLine($"                \"{prop.Name}\",");
        }
        sb.AppendLine("            };");
        sb.AppendLine();

        // Helper method
        sb.AppendLine($@"        private static IOrderedQueryable<{endpoint.FullTypeName}> ApplyOrder<TKey>(
            IQueryable<{endpoint.FullTypeName}> query,
            bool isFirst,
            bool descending,
            Expression<Func<{endpoint.FullTypeName}, TKey>> selector)
        {{
            if (isFirst)
            {{
                return descending
                    ? query.OrderByDescending(selector)
                    : query.OrderBy(selector);
            }}
            return descending
                ? ((IOrderedQueryable<{endpoint.FullTypeName}>)query).ThenByDescending(selector)
                : ((IOrderedQueryable<{endpoint.FullTypeName}>)query).ThenBy(selector);
        }}");

        sb.AppendLine("    }");
        sb.AppendLine("}");

        return sb.ToString();
    }

    private static void EmitDiExtensions(SourceProductionContext context, HashSet<string> namespaces, List<string> registrations)
    {
        if (registrations.Count == 0) return;

        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated />");
        sb.AppendLine("#nullable enable");
        sb.AppendLine("using Microsoft.Extensions.DependencyInjection;");
        sb.AppendLine("using Microsoft.Extensions.DependencyInjection.Extensions;");
        sb.AppendLine("using KyrolusSous.EndpointKit.Core;");
        foreach (var ns in namespaces.OrderBy(n => n))
        {
            sb.AppendLine($"using {ns};");
        }
        sb.AppendLine();
        sb.AppendLine("namespace KyrolusSous.EndpointKit.Generated");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>Generated extension methods for registering AOT endpoint services.</summary>");
        sb.AppendLine("    public static class KyrolusEndpointGeneratedServiceCollectionExtensions");
        sb.AppendLine("    {");
        sb.AppendLine("        /// <summary>Registers all generated property accessors, filter builders, and order builders.</summary>");
        sb.AppendLine("        public static IServiceCollection AddKyrolusGeneratedEndpoints(this IServiceCollection services)");
        sb.AppendLine("        {");
        foreach (var reg in registrations)
        {
            sb.AppendLine(reg);
        }
        sb.AppendLine("            return services;");
        sb.AppendLine("        }");
        sb.AppendLine("    }");
        sb.AppendLine("}");

        context.AddSource("KyrolusEndpointGeneratedServiceCollectionExtensions.g.cs", SourceText.From(sb.ToString(), Encoding.UTF8));
    }

    private static void EmitEndpointHandlerRegistry(SourceProductionContext context, List<EndpointInfo> endpoints)
    {
        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated />");
        sb.AppendLine("#nullable enable");
        sb.AppendLine("using System;");
        sb.AppendLine("using System.Collections.Generic;");
        sb.AppendLine("using KyrolusSous.EndpointKit.Core;");
        sb.AppendLine();
        sb.AppendLine("namespace KyrolusSous.EndpointKit.Generated");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>Registry of all generated endpoint types.</summary>");
        sb.AppendLine("    public static class KyrolusEndpointRegistry");
        sb.AppendLine("    {");
        sb.AppendLine("        /// <summary>Gets all entity types that have generated endpoint support.</summary>");
        sb.AppendLine("        public static IReadOnlyList<KyrolusEndpointMetadata> GetRegisteredEndpoints()");
        sb.AppendLine("            => new KyrolusEndpointMetadata[]");
        sb.AppendLine("            {");

        foreach (var ep in endpoints)
        {
            sb.AppendLine($"                new(\"{ep.TypeName}\", typeof({ep.FullTypeName}), \"{ep.KeyProperty}\", typeof({ep.KeyType}), {(ep.SoftDeleteProperty is not null ? $"\"{ep.SoftDeleteProperty}\"" : "null")}, {(ep.TenantIdProperty is not null ? $"\"{ep.TenantIdProperty}\"" : "null")}, {ep.EnableFiltering.ToString().ToLower()}, {ep.EnableOrdering.ToString().ToLower()}),");
        }

        sb.AppendLine("            };");
        sb.AppendLine("    }");
        sb.AppendLine("}");

        context.AddSource("KyrolusEndpointRegistry.g.cs", SourceText.From(sb.ToString(), Encoding.UTF8));
    }

